window.DATA = {"cards":[{"id":"c000","term":"Person-in-environment (PIE)","def":"Assessing a client within their social, physical, economic, and cultural context rather than as an isolated individual. The foundational social work perspective.","cat":"HBSE"},{"id":"c001","term":"Systems theory","def":"Framework viewing individuals as parts of interacting subsystems; change in one part produces change throughout.","cat":"HBSE"},{"id":"c002","term":"Homeostasis","def":"A system's tendency to maintain equilibrium, often by resisting change — including healthy change.","cat":"HBSE"},{"id":"c003","term":"Equifinality","def":"Different starting conditions can produce the same end state.","cat":"HBSE"},{"id":"c004","term":"Multifinality","def":"The same starting condition can produce different end states.","cat":"HBSE"},{"id":"c005","term":"Entropy vs. negentropy","def":"Tendency of a closed system toward disorder and decline vs. an open system's movement toward growth and organization.","cat":"HBSE"},{"id":"c006","term":"Boundary (systems)","def":"The line defining who is inside a system and how information crosses it; can be rigid, clear, or diffuse.","cat":"HBSE"},{"id":"c007","term":"Differentiation of self","def":"Bowen's concept: the capacity to balance emotional closeness with autonomous thinking under stress.","cat":"HBSE"},{"id":"c008","term":"Triangulation","def":"Drawing a third party into a two-person conflict to diffuse tension, stabilizing the pair at the third party's expense.","cat":"HBSE"},{"id":"c009","term":"Enmeshment","def":"Boundaries so diffuse that individual autonomy is lost; over-involvement.","cat":"HBSE"},{"id":"c010","term":"Disengagement","def":"Boundaries so rigid that support and emotional connection do not pass between members.","cat":"HBSE"},{"id":"c011","term":"Identified patient","def":"The family member who carries and expresses the symptom on behalf of the whole system.","cat":"HBSE"},{"id":"c012","term":"Scapegoating","def":"Assigning blame for family dysfunction to one member, protecting the system from examining itself.","cat":"HBSE"},{"id":"c013","term":"Family homeostasis","def":"A family's resistance to change in order to preserve familiar roles, even dysfunctional ones.","cat":"HBSE"},{"id":"c014","term":"Double bind","def":"Contradictory messages at different levels where the receiver cannot respond correctly or comment on the contradiction.","cat":"HBSE"},{"id":"c015","term":"Genogram","def":"A multigenerational family diagram mapping relationships, patterns, and history.","cat":"HBSE"},{"id":"c016","term":"Ecomap","def":"A diagram of a client system's connections to external resources and institutions.","cat":"HBSE"},{"id":"c017","term":"Zone of proximal development","def":"Vygotsky: the gap between what a learner can do independently and what they can do with guidance.","cat":"HBSE"},{"id":"c018","term":"Scaffolding","def":"Temporary support that is gradually withdrawn as competence develops.","cat":"HBSE"},{"id":"c019","term":"Self-efficacy","def":"Bandura: belief in one's own capacity to execute a behavior and succeed.","cat":"HBSE"},{"id":"c020","term":"Modeling / vicarious learning","def":"Learning a behavior by observing another person perform it and seeing the consequences.","cat":"HBSE"},{"id":"c021","term":"Separation-individuation","def":"Mahler: the process by which a child develops a self distinct from the primary caregiver.","cat":"HBSE"},{"id":"c022","term":"Object constancy","def":"Capacity to maintain a stable internal image of a caregiver during absence or conflict.","cat":"HBSE"},{"id":"c023","term":"Secure attachment","def":"Child uses caregiver as a secure base, shows distress at separation, is comforted on reunion.","cat":"HBSE"},{"id":"c024","term":"Anxious/ambivalent attachment","def":"Child is intensely distressed at separation and simultaneously seeks and resists comfort on reunion.","cat":"HBSE"},{"id":"c025","term":"Avoidant attachment","def":"Child shows little distress at separation and actively avoids the caregiver on reunion.","cat":"HBSE"},{"id":"c026","term":"Disorganized attachment","def":"Contradictory, fearful, or freezing behavior toward the caregiver; most associated with maltreatment.","cat":"HBSE"},{"id":"c027","term":"Object permanence","def":"Piaget: understanding that objects continue to exist when out of sight; sensorimotor stage.","cat":"HBSE"},{"id":"c028","term":"Conservation","def":"Piaget: understanding that quantity stays constant despite change in shape; concrete operational stage.","cat":"HBSE"},{"id":"c029","term":"Formal operations","def":"Piaget: capacity for abstract and hypothetical reasoning, emerging in adolescence.","cat":"HBSE"},{"id":"c030","term":"Erikson: trust vs. mistrust","def":"Infancy; reliable caregiving builds basic trust in the world.","cat":"HBSE"},{"id":"c031","term":"Erikson: autonomy vs. shame and doubt","def":"Toddlerhood; developing will and self-control.","cat":"HBSE"},{"id":"c032","term":"Erikson: initiative vs. guilt","def":"Preschool; purposeful action and planning.","cat":"HBSE"},{"id":"c033","term":"Erikson: industry vs. inferiority","def":"School age; competence through accomplishment.","cat":"HBSE"},{"id":"c034","term":"Erikson: identity vs. role confusion","def":"Adolescence; consolidating a coherent sense of self.","cat":"HBSE"},{"id":"c035","term":"Erikson: intimacy vs. isolation","def":"Young adulthood; forming committed relationships.","cat":"HBSE"},{"id":"c036","term":"Erikson: generativity vs. stagnation","def":"Middle adulthood; contributing to the next generation.","cat":"HBSE"},{"id":"c037","term":"Erikson: integrity vs. despair","def":"Late adulthood; accepting one's life as meaningful.","cat":"HBSE"},{"id":"c038","term":"Kubler-Ross stages","def":"Denial, anger, bargaining, depression, acceptance; non-linear and not universal.","cat":"HBSE"},{"id":"c039","term":"Intersectionality","def":"Overlapping identities producing compounded and distinct experiences of oppression.","cat":"Diversity"},{"id":"c040","term":"Cultural humility","def":"Ongoing self-reflection, openness, and redressing power imbalance — contrasted with competence as a fixed endpoint.","cat":"Diversity"},{"id":"c041","term":"Acculturation","def":"Adapting to a dominant culture while retaining elements of the culture of origin.","cat":"Diversity"},{"id":"c042","term":"Assimilation","def":"Absorption into the dominant culture with loss of the original cultural identity.","cat":"Diversity"},{"id":"c043","term":"Microaggression","def":"Brief, often unintentional verbal or behavioral slight communicating a hostile message about identity.","cat":"Diversity"},{"id":"c044","term":"Institutional racism","def":"Discrimination embedded in the policies and practices of organizations rather than individual intent.","cat":"Diversity"},{"id":"c045","term":"Internalized oppression","def":"Adoption by a marginalized person of the dominant culture's negative beliefs about their own group.","cat":"Diversity"},{"id":"c046","term":"Empowerment practice","def":"Increasing a client's personal, interpersonal, and political power to act on their own behalf.","cat":"Diversity"},{"id":"c047","term":"Strengths perspective","def":"Practice organized around client capacities, resources, and resilience rather than deficits.","cat":"Diversity"},{"id":"c048","term":"Mental status exam (MSE)","def":"Structured observation of appearance, behavior, speech, mood, affect, thought process, thought content, cognition, insight, and judgment.","cat":"Assessment"},{"id":"c049","term":"Mood vs. affect","def":"Mood is the client's reported sustained internal state; affect is your observation of its outward expression.","cat":"Assessment"},{"id":"c050","term":"Blunted affect","def":"Significantly reduced intensity of emotional expression.","cat":"Assessment"},{"id":"c051","term":"Flat affect","def":"Near-total absence of emotional expression.","cat":"Assessment"},{"id":"c052","term":"Labile affect","def":"Rapid, abrupt shifts in emotional expression.","cat":"Assessment"},{"id":"c053","term":"Incongruent affect","def":"Emotional expression that does not match the content being discussed.","cat":"Assessment"},{"id":"c054","term":"Circumstantial thought","def":"Speech that includes excessive detail but eventually arrives at the point.","cat":"Assessment"},{"id":"c055","term":"Tangential thought","def":"Speech that veers off and never returns to the point.","cat":"Assessment"},{"id":"c056","term":"Loose associations","def":"Speech shifting between unrelated ideas with no logical connection.","cat":"Assessment"},{"id":"c057","term":"Flight of ideas","def":"Rapid, continuous speech with abrupt topic changes, often loosely connected; associated with mania.","cat":"Assessment"},{"id":"c058","term":"Thought blocking","def":"Abrupt interruption of speech mid-thought with no recall of the intended content.","cat":"Assessment"},{"id":"c059","term":"Perseveration","def":"Repetition of a word, phrase, or idea beyond its relevance.","cat":"Assessment"},{"id":"c060","term":"Delusion","def":"A fixed false belief maintained despite contradicting evidence.","cat":"Assessment"},{"id":"c061","term":"Hallucination","def":"A sensory perception occurring without any external stimulus.","cat":"Assessment"},{"id":"c062","term":"Illusion","def":"A misinterpretation of a real external stimulus.","cat":"Assessment"},{"id":"c063","term":"Ideas of reference","def":"Belief that unrelated external events carry specific personal meaning.","cat":"Assessment"},{"id":"c064","term":"Anhedonia","def":"Loss of the capacity to experience pleasure.","cat":"Assessment"},{"id":"c065","term":"Avolition","def":"Marked reduction in motivation to initiate and sustain purposeful activity.","cat":"Assessment"},{"id":"c066","term":"Alogia","def":"Poverty of speech output; a negative symptom of schizophrenia.","cat":"Assessment"},{"id":"c067","term":"Depersonalization","def":"Detachment from one's own body, thoughts, or sense of self.","cat":"Assessment"},{"id":"c068","term":"Derealization","def":"Experience of the external world as unreal, dreamlike, or distorted.","cat":"Assessment"},{"id":"c069","term":"Egosyntonic","def":"Symptoms or traits experienced as consistent with one's self-concept; often not distressing.","cat":"Assessment"},{"id":"c070","term":"Egodystonic","def":"Symptoms experienced as foreign to the self and distressing; more likely to motivate help-seeking.","cat":"Assessment"},{"id":"c071","term":"Differential diagnosis","def":"Systematically distinguishing among disorders with overlapping presentations.","cat":"Assessment"},{"id":"c072","term":"Rule out","def":"Designation that a condition is being actively considered but not yet excluded or confirmed.","cat":"Assessment"},{"id":"c073","term":"Provisional diagnosis","def":"Assigned when criteria are likely met but confirming information is incomplete.","cat":"Assessment"},{"id":"c074","term":"Malingering","def":"Intentional production of symptoms for an external incentive such as money, drugs, or avoiding duty.","cat":"Assessment"},{"id":"c075","term":"Factitious disorder","def":"Intentional production of symptoms motivated by assuming the sick role, without external reward.","cat":"Assessment"},{"id":"c076","term":"Somatic symptom disorder","def":"Distressing physical symptoms with disproportionate thoughts, feelings, and behaviors about them.","cat":"Assessment"},{"id":"c077","term":"Conversion disorder","def":"Neurological symptoms incompatible with known conditions, not intentionally produced.","cat":"Assessment"},{"id":"c078","term":"Prodromal phase","def":"Early, subtle warning signs preceding full symptom onset.","cat":"Assessment"},{"id":"c079","term":"Lethality assessment","def":"Evaluating suicidal ideation, intent, plan, means, access, prior attempts, and protective factors.","cat":"Assessment"},{"id":"c080","term":"Protective factors","def":"Conditions reducing risk — social support, treatment engagement, religious prohibition, dependents, future orientation.","cat":"Assessment"},{"id":"c081","term":"Tolerance","def":"Needing increasing amounts of a substance to achieve the original effect.","cat":"Assessment"},{"id":"c082","term":"Withdrawal","def":"Physiological and psychological symptoms following reduction or cessation of a substance.","cat":"Assessment"},{"id":"c083","term":"Dual diagnosis / co-occurring","def":"Presence of a substance use disorder alongside another mental health disorder; treat concurrently.","cat":"Assessment"},{"id":"c084","term":"Z codes","def":"DSM-5-TR codes for psychosocial and environmental problems affecting care that are not mental disorders.","cat":"Assessment"},{"id":"c085","term":"Collateral contact","def":"Information obtained from a third party with client consent to supplement assessment.","cat":"Assessment"},{"id":"c086","term":"Transference","def":"The client's unconscious redirection of feelings from past relationships onto the practitioner.","cat":"Intervention"},{"id":"c087","term":"Countertransference","def":"The practitioner's emotional reaction to the client, often rooted in the practitioner's own history.","cat":"Intervention"},{"id":"c088","term":"Projection","def":"Attributing one's own unacceptable impulses or feelings to another person.","cat":"Intervention"},{"id":"c089","term":"Displacement","def":"Redirecting an impulse from a threatening target onto a safer substitute.","cat":"Intervention"},{"id":"c090","term":"Reaction formation","def":"Behaving in a manner opposite to an unacceptable impulse.","cat":"Intervention"},{"id":"c091","term":"Sublimation","def":"Channeling unacceptable impulses into socially valued activity; considered the most mature defense.","cat":"Intervention"},{"id":"c092","term":"Splitting","def":"Inability to hold positive and negative qualities together; people are viewed as all good or all bad.","cat":"Intervention"},{"id":"c093","term":"Intellectualization","def":"Using abstract reasoning to avoid the emotional content of an experience.","cat":"Intervention"},{"id":"c094","term":"Rationalization","def":"Constructing acceptable explanations to justify behavior driven by unacceptable motives.","cat":"Intervention"},{"id":"c095","term":"Regression","def":"Reverting to an earlier developmental stage of functioning under stress.","cat":"Intervention"},{"id":"c096","term":"Undoing","def":"Performing an act intended to negate or atone for a prior unacceptable thought or act.","cat":"Intervention"},{"id":"c097","term":"Denial","def":"Refusing to accept an external reality because it is too threatening.","cat":"Intervention"},{"id":"c098","term":"Repression vs. suppression","def":"Unconscious exclusion of material from awareness vs. deliberate conscious setting aside.","cat":"Intervention"},{"id":"c099","term":"Working alliance","def":"The collaborative bond, agreement on goals, and agreement on tasks; the strongest predictor of outcome.","cat":"Intervention"},{"id":"c100","term":"Cognitive distortion","def":"A systematic error in thinking — catastrophizing, all-or-nothing, mind reading, overgeneralization, personalization.","cat":"Intervention"},{"id":"c101","term":"Cognitive restructuring","def":"Identifying, testing, and replacing automatic negative thoughts.","cat":"Intervention"},{"id":"c102","term":"Systematic desensitization","def":"Graded exposure to feared stimuli paired with a relaxation response.","cat":"Intervention"},{"id":"c103","term":"Flooding","def":"Immediate prolonged exposure to the maximum-intensity feared stimulus.","cat":"Intervention"},{"id":"c104","term":"Exposure and response prevention","def":"Exposure to an obsessional trigger while blocking the compulsive response; first-line for OCD.","cat":"Intervention"},{"id":"c105","term":"Positive reinforcement","def":"Adding a stimulus following a behavior to increase its frequency.","cat":"Intervention"},{"id":"c106","term":"Negative reinforcement","def":"Removing an aversive stimulus following a behavior to increase its frequency. It increases behavior.","cat":"Intervention"},{"id":"c107","term":"Punishment","def":"Any consequence that decreases the frequency of a behavior.","cat":"Intervention"},{"id":"c108","term":"Extinction","def":"Withholding reinforcement until a previously reinforced behavior decreases; expect an initial burst.","cat":"Intervention"},{"id":"c109","term":"Shaping","def":"Reinforcing successive approximations toward a target behavior.","cat":"Intervention"},{"id":"c110","term":"Intermittent reinforcement","def":"Reinforcing only some responses; produces behavior most resistant to extinction.","cat":"Intervention"},{"id":"c111","term":"Token economy","def":"Structured system of earned secondary reinforcers exchangeable for rewards.","cat":"Intervention"},{"id":"c112","term":"Precontemplation","def":"Stage of change: no recognition of a problem and no intention to change.","cat":"Intervention"},{"id":"c113","term":"Contemplation","def":"Stage of change: ambivalent awareness of a problem without commitment to act.","cat":"Intervention"},{"id":"c114","term":"Preparation","def":"Stage of change: intending to act soon and taking small preliminary steps.","cat":"Intervention"},{"id":"c115","term":"Action","def":"Stage of change: actively modifying behavior and environment.","cat":"Intervention"},{"id":"c116","term":"Maintenance","def":"Stage of change: sustaining gains and preventing relapse.","cat":"Intervention"},{"id":"c117","term":"Motivational interviewing","def":"Collaborative, client-centered method for eliciting and strengthening motivation for change.","cat":"Intervention"},{"id":"c118","term":"OARS","def":"Motivational interviewing core skills: open questions, affirmations, reflective listening, summaries.","cat":"Intervention"},{"id":"c119","term":"Rolling with resistance","def":"Avoiding argument and reframing resistance as information rather than opposition.","cat":"Intervention"},{"id":"c120","term":"Change talk","def":"Client statements favoring change; the practitioner selectively elicits and reinforces them.","cat":"Intervention"},{"id":"c121","term":"Miracle question","def":"Solution-focused technique asking the client to describe life if the problem vanished overnight.","cat":"Intervention"},{"id":"c122","term":"Exception question","def":"Solution-focused technique identifying times the problem was absent or less severe.","cat":"Intervention"},{"id":"c123","term":"Scaling question","def":"Asking the client to rate a condition numerically to establish a baseline and increments of change.","cat":"Intervention"},{"id":"c124","term":"Externalizing","def":"Narrative technique separating the person from the problem so the problem can be addressed as distinct.","cat":"Intervention"},{"id":"c125","term":"Reframing","def":"Offering an alternative interpretation of a situation that opens new response options.","cat":"Intervention"},{"id":"c126","term":"Paradoxical directive","def":"Prescribing the symptom so the client experiences control over it.","cat":"Intervention"},{"id":"c127","term":"Joining","def":"Structural family therapy: the therapist temporarily accommodates to the family system to gain entry.","cat":"Intervention"},{"id":"c128","term":"Enactment","def":"Having a family perform an interaction in session so the therapist can observe and intervene live.","cat":"Intervention"},{"id":"c129","term":"Distress tolerance","def":"DBT skill set for surviving crisis without making the situation worse.","cat":"Intervention"},{"id":"c130","term":"Radical acceptance","def":"DBT skill of fully accepting reality as it is to end suffering added by resistance.","cat":"Intervention"},{"id":"c131","term":"Wise mind","def":"DBT integration of emotion mind and reasonable mind.","cat":"Intervention"},{"id":"c132","term":"Dialectic","def":"Holding two apparently opposing truths simultaneously, as in acceptance and change.","cat":"Intervention"},{"id":"c133","term":"Trauma-informed care","def":"Practice organized around safety, trustworthiness, choice, collaboration, and empowerment; asks what happened rather than what is wrong.","cat":"Intervention"},{"id":"c134","term":"ACEs","def":"Adverse Childhood Experiences; higher scores show a dose-response relationship with later health and behavioral outcomes.","cat":"Intervention"},{"id":"c135","term":"Window of tolerance","def":"The arousal range in which a person can process experience without becoming hyper- or hypoaroused.","cat":"Intervention"},{"id":"c136","term":"Grounding techniques","def":"Sensory strategies returning a dissociating or flashbacking client to present-moment awareness.","cat":"Intervention"},{"id":"c137","term":"Psychoeducation","def":"Teaching clients and families about a condition, its course, and coping strategies.","cat":"Intervention"},{"id":"c138","term":"Crisis intervention","def":"Time-limited, present-focused work aimed at restoring pre-crisis functioning.","cat":"Intervention"},{"id":"c139","term":"Group stages","def":"Forming, storming, norming, performing, adjourning.","cat":"Intervention"},{"id":"c140","term":"Universality","def":"Yalom curative factor: recognizing that others share the same struggle.","cat":"Intervention"},{"id":"c141","term":"Group cohesion","def":"The bond and sense of belonging among members; the group analogue of the therapeutic alliance.","cat":"Intervention"},{"id":"c142","term":"Open vs. closed group","def":"Members may join throughout vs. membership fixed at the start.","cat":"Intervention"},{"id":"c143","term":"Task vs. treatment group","def":"Group formed to accomplish an external objective vs. to meet members' socioemotional needs.","cat":"Intervention"},{"id":"c144","term":"Least restrictive environment","def":"The setting that meets the client's needs while preserving the greatest possible autonomy.","cat":"Intervention"},{"id":"c145","term":"Termination","def":"Planned, prepared ending of the professional relationship including review of gains and referral as needed.","cat":"Intervention"},{"id":"c146","term":"Abandonment","def":"Unethical unilateral discontinuation of services without notice, transition, or referral.","cat":"Intervention"},{"id":"c147","term":"NASW core values","def":"Service, social justice, dignity and worth of the person, importance of human relationships, integrity, competence.","cat":"Ethics"},{"id":"c148","term":"Self-determination","def":"The client's right to make their own decisions; limited only when risk is serious, foreseeable, and imminent.","cat":"Ethics"},{"id":"c149","term":"Informed consent","def":"Clear disclosure of purpose, risks, benefits, alternatives, costs, and limits, given in understandable language.","cat":"Ethics"},{"id":"c150","term":"Assent","def":"Agreement from a minor or a client lacking legal capacity, obtained alongside a guardian's consent.","cat":"Ethics"},{"id":"c151","term":"Confidentiality","def":"The ethical duty not to disclose client information without authorization.","cat":"Ethics"},{"id":"c152","term":"Privileged communication","def":"A legal protection preventing compelled disclosure in court; belongs to the client and varies by jurisdiction.","cat":"Ethics"},{"id":"c153","term":"Duty to warn and protect (Tarasoff)","def":"Obligation to act when a client poses a serious threat of violence to a reasonably identifiable victim.","cat":"Ethics"},{"id":"c154","term":"Mandated reporting","def":"Legal obligation to report suspected abuse or neglect of children, elders, and dependent adults on reasonable suspicion, not proof.","cat":"Ethics"},{"id":"c155","term":"Dual relationship","def":"Any role with a client beyond the professional one; risk of impaired judgment and exploitation.","cat":"Ethics"},{"id":"c156","term":"Boundary crossing vs. violation","def":"A departure from usual practice that may be benign or clinically useful vs. one that harms or exploits.","cat":"Ethics"},{"id":"c157","term":"Conflict of interest","def":"Any competing personal, financial, or professional interest that could compromise professional judgment.","cat":"Ethics"},{"id":"c158","term":"Scope of practice","def":"The activities a practitioner is legally authorized and clinically competent to perform.","cat":"Ethics"},{"id":"c159","term":"Cultural competence obligation","def":"Ethical requirement to obtain the knowledge and skills to serve diverse populations effectively.","cat":"Ethics"},{"id":"c160","term":"Supervision vs. consultation","def":"Supervision carries authority, evaluation, and legal responsibility; consultation is advisory and non-binding.","cat":"Ethics"},{"id":"c161","term":"Vicarious liability","def":"A supervisor's legal responsibility for the professional actions of a supervisee.","cat":"Ethics"},{"id":"c162","term":"Malpractice","def":"Professional negligence: a duty existed, the standard of care was breached, and the breach caused harm.","cat":"Ethics"},{"id":"c163","term":"Standard of care","def":"What a reasonably prudent practitioner with similar training would do in similar circumstances.","cat":"Ethics"},{"id":"c164","term":"Impairment","def":"A practitioner condition — illness, substance use, distress — interfering with competent practice.","cat":"Ethics"},{"id":"c165","term":"Duty to report a colleague","def":"Obligation to address a colleague's unethical conduct or impairment, first directly when feasible.","cat":"Ethics"},{"id":"c166","term":"Record retention","def":"Duty to store, secure, and dispose of records per law and to protect confidentiality after termination or death.","cat":"Ethics"},{"id":"c167","term":"Administrative supervision","def":"Supervisory function covering workload, policy, compliance, and accountability.","cat":"Supervision"},{"id":"c168","term":"Educational supervision","def":"Supervisory function developing the supervisee's knowledge, skills, and clinical reasoning.","cat":"Supervision"},{"id":"c169","term":"Supportive supervision","def":"Supervisory function addressing morale, stress, and job satisfaction.","cat":"Supervision"},{"id":"c170","term":"Parallel process","def":"Dynamics from the client relationship unconsciously reenacted within the supervisory relationship.","cat":"Supervision"},{"id":"c171","term":"Burnout","def":"Emotional exhaustion, depersonalization, and reduced accomplishment arising from chronic workplace stress.","cat":"Supervision"},{"id":"c172","term":"Compassion fatigue","def":"Depletion resulting from sustained empathic engagement with suffering clients.","cat":"Supervision"},{"id":"c173","term":"Vicarious trauma","def":"Lasting change in the practitioner's worldview from cumulative exposure to clients' trauma material.","cat":"Supervision"},{"id":"c174","term":"Reliability","def":"Consistency of a measurement across time, items, or raters.","cat":"Research"},{"id":"c175","term":"Validity","def":"The degree to which an instrument measures what it claims to measure.","cat":"Research"},{"id":"c176","term":"Independent variable","def":"The variable manipulated or presumed to cause change.","cat":"Research"},{"id":"c177","term":"Dependent variable","def":"The outcome variable that is measured.","cat":"Research"},{"id":"c178","term":"Single-subject design","def":"Repeated measurement of one client system across baseline (A) and intervention (B) phases.","cat":"Research"},{"id":"c179","term":"Formative evaluation","def":"Assessment conducted during implementation to guide improvement.","cat":"Research"},{"id":"c180","term":"Summative evaluation","def":"Assessment conducted at completion to judge overall effectiveness.","cat":"Research"},{"id":"c181","term":"Needs assessment","def":"Systematic study identifying gaps between current conditions and desired conditions in a population.","cat":"Research"},{"id":"c182","term":"Correlation vs. causation","def":"Association between variables does not establish that one produces the other.","cat":"Research"},{"id":"c183","term":"Random assignment","def":"Allocating participants to conditions by chance to equalize groups and support causal inference.","cat":"Research"},{"id":"c184","term":"Purposive sampling","def":"Non-probability selection of participants who possess characteristics relevant to the study.","cat":"Research"},{"id":"c185","term":"Type I vs. Type II error","def":"Rejecting a true null hypothesis (false positive) vs. failing to reject a false one (false negative).","cat":"Research"},{"id":"c186","term":"Evidence-based practice","def":"Integrating best available research, practitioner expertise, and client values and preferences.","cat":"Research"},{"id":"c187","term":"SSI","def":"Supplemental Security Income; needs-based cash assistance for aged, blind, or disabled persons with limited income.","cat":"Policy"},{"id":"c188","term":"SSDI","def":"Social Security Disability Insurance; benefits based on the worker's own contribution and work history.","cat":"Policy"},{"id":"c189","term":"Medicaid","def":"Joint federal-state health coverage based on income and categorical eligibility.","cat":"Policy"},{"id":"c190","term":"Medicare","def":"Federal health insurance based on age 65+ or qualifying disability; Parts A, B, C, and D.","cat":"Policy"},{"id":"c191","term":"TANF","def":"Temporary Assistance for Needy Families; time-limited cash assistance with work requirements.","cat":"Policy"},{"id":"c192","term":"IDEA","def":"Individuals with Disabilities Education Act; guarantees free appropriate public education in the least restrictive environment.","cat":"Policy"},{"id":"c193","term":"IEP","def":"Individualized Education Program; legally binding special education plan under IDEA.","cat":"Policy"},{"id":"c194","term":"504 plan","def":"Accommodation plan under the Rehabilitation Act for students who do not qualify for an IEP.","cat":"Policy"},{"id":"c195","term":"ADA","def":"Americans with Disabilities Act; prohibits disability discrimination and requires reasonable accommodation.","cat":"Policy"},{"id":"c196","term":"HIPAA","def":"Federal law governing the privacy and security of protected health information.","cat":"Policy"},{"id":"c197","term":"FERPA","def":"Federal law protecting the privacy of student education records.","cat":"Policy"},{"id":"c198","term":"42 CFR Part 2","def":"Federal regulation providing heightened confidentiality protection for substance use disorder treatment records.","cat":"Policy"},{"id":"c199","term":"Utilization review","def":"Payer process determining whether services meet medical necessity criteria for authorization or continued stay.","cat":"Policy"},{"id":"c200","term":"Case management","def":"Coordinating, linking, and monitoring services across providers on a client's behalf.","cat":"Policy"},{"id":"c201","term":"Advocacy","def":"Acting with or on behalf of clients to influence decisions, policies, or resource allocation.","cat":"Policy"},{"id":"c202","term":"Social action","def":"Organized effort to change institutions or policy to achieve social justice.","cat":"Policy"},{"id":"c203","term":"Community organizing","def":"Mobilizing community members to identify shared concerns and act collectively.","cat":"Policy"},{"id":"c204","term":"Guardianship vs. conservatorship","def":"Court-appointed authority over personal and medical decisions vs. over financial affairs.","cat":"Policy"},{"id":"c205","term":"Advance directive","def":"Document specifying a person's treatment preferences and decision-maker if they lose capacity.","cat":"Policy"},{"id":"c206","term":"Civil commitment","def":"Involuntary psychiatric hospitalization based on danger to self, danger to others, or grave disability.","cat":"Policy"}],"questions":[{"cat":"Assessment","stem":"A social worker documents that a client \"answered every question with lengthy background detail and multiple digressions but ultimately answered each one.\" This describes:","choices":["Loose associations","Tangential thought process","Flight of ideas","Circumstantial thought process"],"answer":3,"label":"Circumstantial","why":"Excessive detail but the point is eventually reached. Tangential (A) never arrives.","id":"q009","n":9},{"cat":"Diversity","stem":"A colleague tells a Latina social worker she is 'so articulate' after a case presentation. This comment is best characterized as:","choices":["Countertransference","A microaggression","A compliment with no clinical significance","Overt discrimination"],"answer":1,"label":"A microaggression","why":"The remark carries an implied assumption about the group's expected ability. Intent does not determine whether something is a microaggression; impact does.","id":"q059","n":59},{"cat":"Ethics","stem":"A social worker in a rural county learns that a new client is the sister of her child's soccer coach and attends the same small church. The MOST appropriate response is to:","choices":["Discuss the overlap with the client, set clear expectations, and document the plan","Accept the case and stop attending church","Accept the case and say nothing, since the overlap is incidental","Decline the case to avoid a dual relationship"],"answer":0,"label":"Discuss the overlap, set expectations, document","why":"Unavoidable community overlap is managed, not concealed (B) or automatically refused (A) — declining every overlapping case in a rural county would leave clients without services.","id":"q029","n":29},{"cat":"HBSE","stem":"A social worker meets with a family in which the 14-year-old son has been referred for behavioral problems. During the session, whenever the parents begin to disagree about finances, the son interrupts with a joke or a provocation and both parents redirect their attention to him. This pattern BEST illustrates:","choices":["Triangulation","Scapegoating","Double bind","Enmeshment"],"answer":0,"label":"Triangulation","why":"The son is pulled into the parental dyad to defuse marital tension. Scapegoating (A) would require the family assigning blame to him for the family's problems, which isn't described. Enmeshment (C) describes boundary diffuseness generally, not this specific three-person maneuver.","id":"q001","n":1},{"cat":"Intervention","stem":"A client in her third session says she doesn't see any real problem with her drinking and only came because her employer required it. The MOST appropriate intervention is to:","choices":["Develop a concrete sobriety plan with weekly goals","Refer to an intensive outpatient program","Present the medical consequences of continued drinking","Explore the client's own view of her situation and any concerns she has"],"answer":3,"label":"Explore the client's own view and any concerns","why":"The client is precontemplative and externally mandated. Consequences (A), action plans (B), and referral (D) are all stage-mismatched.","id":"q019","n":19},{"cat":"Policy","stem":"A supervisee describes feeling helpless and inadequate with a client who insists nothing will help. In supervision, the supervisor notices she feels equally helpless and inadequate with the supervisee. This is BEST described as:","choices":["Countertransference","Parallel process","Vicarious trauma","Projective identification"],"answer":1,"label":"Parallel process","why":"The client-supervisee dynamic is reenacted in the supervisor-supervisee relationship.","id":"q037","n":37},{"cat":"Research","stem":"A researcher measures whether a new group intervention reduces depression scores. The depression score is:","choices":["The independent variable","A control variable","A confounding variable","The dependent variable"],"answer":3,"label":"The dependent variable","why":"The dependent variable is the measured outcome. The intervention is the independent variable.","id":"q200","n":200},{"cat":"Supervision","stem":"A supervisee asks the supervisor to keep her personal struggles confidential from the agency. The supervisor should:","choices":["Report the conversation to human resources","Clarify the limits of confidentiality in supervision, including client safety and performance obligations","Agree without qualification","Refuse to discuss anything personal"],"answer":1,"label":"Clarify the limits of confidentiality in supervision, including client safety and performance obligations","why":"Supervision carries evaluative and administrative functions, so its confidentiality is limited and those limits must be explicit.","id":"q195","n":195},{"cat":"Assessment","stem":"A client reports feeling \"fine\" while crying throughout the session and describing a recent loss in a flat, expressionless voice. The social worker should document:","choices":["Blunted mood","Affect incongruent with content","Labile mood","Congruent affect"],"answer":1,"label":"Affect incongruent with content","why":"Mood is what the client reports (\"fine\"); affect is what you observe. The mismatch between reported state, observed expression, and content is the finding. Note that \"blunted mood\" (D) misapplies the term — blunting describes affect, not mood.","id":"q010","n":10},{"cat":"Diversity","stem":"A social worker realizes she knows little about a client's religious tradition. The most appropriate response is to:","choices":["Proceed without addressing it, since faith is private","Ask the client about the role the tradition plays in her life","Research the tradition and avoid raising it in session","Refer the client to a practitioner of the same faith"],"answer":1,"label":"Ask the client about the role the tradition plays in her life","why":"The client is the expert on her own experience. Cultural humility means inquiring rather than assuming or outsourcing.","id":"q060","n":60}],"meta":{"total":217,"free":10,"split":true}};
